  _sp  = Geom::Point3d.new(17500.0.mm, 136500.0.mm, 0.0.mm)
  _ep  = Geom::Point3d.new(26500.0.mm, 136500.0.mm, 0.0.mm)
  _vec = _sp.vector_to(_ep)
  _len = _sp.distance(_ep)
  if _len < 1.mm || !_vec.valid?
    puts "SKIP B_Y_112: zero-length"
  else
    _grp = ents.add_group
    _ge  = _grp.entities
    _t   = Geom::Transformation.new(_sp, _vec)
    _raw = [[-150.0, -300.0], [150.0, -300.0],
            [150.0, 300.0], [-150.0, 300.0]]
    _face = _ge.add_face(_raw.map { |p| _t * Geom::Point3d.new(p[0].mm, p[1].mm, 0) })
    _face.pushpull(_len) if _face
    _grp.layer = get_or_create_layer(layers, "STR-Beams")
    _grp.material = _steel_mat
    _grp.set_attribute("IFC", "Mark",    "B_Y_112")
    _grp.set_attribute("IFC", "Section", "300x600")
    _grp.set_attribute("IFC", "Type",    "beam")
    _grp.name = "B_Y_112"
  end
rescue => e
  puts "SKIP B_Y_112: #{e.message}"
end

